def _pinned_url(src):
    """The download URL at this release's pinned commit, or None."""
    pin = FEED_PINS.get(src.get("repo", ""))
    if not pin or not src.get("path"):
        return None
    return RAW + src["repo"] + "/" + pin + "/" + src["path"]


